"""
  Returns a segment of a string, starting at start_num. The first character in text has
  start_num 1.

  >>> MID("Fluid Flow", 1, 5)
  'Fluid'
  >>> MID("Fluid Flow", 7, 20)
  'Flow'
  >>> MID("Fluid Flow", 20, 5)
  ''
  >>> MID("Fluid Flow", 0, 5)
  Traceback (most recent call last):
  ...
  ValueError: start_num invalid
  """
def MID(text: Any, start_num: Any, num_chars: Any) -> object {
    if (start_num < 1) {
        raise ValueError("start_num invalid");
    }
    return text[(start_num - 1):((start_num - 1) + num_chars)];
}

"""Returns the maximum divider for `value` starting from `start` value"""
def get_div(value: Any, start: Any) -> object {
    div = 1;
    for d in range(start, 0, -1) {
        if ((value % d) == 0) {
            div = d;
            break;
        }
    }
    return div;
}

