"""Convert pitch string to meters.

    Something like -600- is assumed to mean "six-hundreths of an inch".

    >>> _pitch2m("-600-")
    4.233333333333333e-05
    >>> _pitch2m("-1200-")
    2.1166666666666665e-05
    """
def _pitch2m(res: Any) -> object {
    res = int(res[1:-1]);
    return (0.0254 / res);
}

"""
	Checks for existence of a bijection between input sequences
	seq1 and seq2.
	"""
def is_equivalent(seq1: Any, seq2: Any) -> object {
    letters1 = `set(seq1);
    letters2 = `set(seq2);
    distinct_mappings = `set(zip(seq1, seq2));
    return (
        (len(letters1) == len(letters2) == len(distinct_mappings))
        and (len(seq1) == len(seq2))
    );
}

